"""Звести зафіксований вимір і перевірити повноту його чисел без мережі."""
import collections
import gzip
import hashlib
import json
from pathlib import Path

from річ_запис_каталог import КОРІНЬ, записати


def main():
    """Звірити джерела, рядки й підсумок; чесно позначити незавершене мірило полів."""
    тека = КОРІНЬ / 'аудит/проби/річ_запис_каталог_2026_10_30'
    def json_файл(імя):
        """Прочитати один зафіксований JSON."""
        return json.loads((тека / імя).read_text(encoding='utf-8'))
    def рядки(імя):
        """Прочитати всі рядки стисненого протоколу."""
        return [json.loads(р) for р in gzip.decompress((тека / імя).read_bytes()).decode().splitlines()]
    підсумок = json_файл('підсумок.json')
    речі = рядки('читачі.jsonl.gz')
    без_типу = рядки('без_типу.jsonl.gz')
    assert len(речі) == len({р['id'] for р in речі}) == підсумок['оферів']
    assert sum(bool(р['різні']) for р in речі) == підсумок['розбіжних']
    assert len(без_типу) == sum(not р['читачі']['запис_входу']['тип'] for р in речі) == підсумок['без_типу']
    assert dict(collections.Counter(р['причина'] for р in без_типу)) == підсумок['причини']
    assert dict(collections.Counter(к for р in речі for к in р['різні'])) == підсумок['пари']
    for імя, підпис in підсумок['джерела'].items():
        assert hashlib.sha256((КОРІНЬ / імя).read_bytes()).hexdigest() == підпис, імя
    вибірка = json_файл('вибірка.json')
    п3 = json_файл('вибірка_п3.json')
    частки = json_файл('частки.json')
    без_сторінок = json_файл('крамниці_без_сторінок.json')
    assert len(вибірка) == 156 and set(collections.Counter(р['крамниця'] for р in вибірка).values()) == {3}
    assert len(п3) == 144 and set(collections.Counter(р['id'].split('@')[1] for р in п3).values()) == {3}
    assert len({р['url'] for р in п3}) == 144
    assert {р['id'].split('@')[1] for р in п3}.isdisjoint({р['крамниця'] for р in без_сторінок})
    assert len(п3) // 3 + len(без_сторінок) == 52
    for р in п3:
        assert len(gzip.decompress((тека / р['файл']).read_bytes())) > 2000, р['файл']
    assert частки['сторінок'] == 144
    кадри = json_файл('кадри.json')
    assert len(кадри) == 20 and all('файл' in р for р in кадри)
    for р in кадри:
        assert hashlib.sha256((тека / р['файл']).read_bytes()).hexdigest() == р['sha256']
    текст = [
        '# Річ-запис-речі: вимір каталогу 5.3, 30.10.2026 UTC', '',
        'База `main`: `' + підсумок['main_sha'] + '`. Усі числа нижче — саме з цього дерева; SHA256 входів — `підсумок.json`.', '',
        '## Що виміряно', '',
        '- Повний `каталог_повний.xml.gz`: **30 375 оферів, 52 крамниці**. Це записи фіда, включно з відсіченими каналом і не одягом; не кількість речей у кінцевому пулі.',
        '- **2 972** офери з різними виходами типу/слота серед викликаних входів; усі розбіжності — слот, розбіжностей типу немає. Це лічба різних виходів, а не доведена кількість хибно класифікованих речей.',
        '- Серед входів готового запису — **744**: слот класифікатора проти `слот(offer)`/читання запису з перевіркою каналу. Окремо повтор жнив проти класифікатора — **1 430**; опис кадру проти класифікатора — **995 з 10 764** з описом. Ці множини перетинаються.',
        '- **1 231** офер без типу в побудованому записі: причини кожного — `без_типу.jsonl.gz`. Не кожен офер є одягом: зокрема підставки для яєць, гаманець тощо не можна оголосити поломкою словника за самим None.',
        '- Чужі поля (п.3) — **вибірка: 144 сторінки, 48 крамниць по 3** (зерно 11658); 4 крамниці без придатної сторінки — переліком у розділі «Поля з чужого блоку». Це вибірка, не суцільний вимір.',
        '- `джерела/каталог_brief.xml.gz` містить **485** оферів і не використаний як знаменник повного каталогу. Маніфести `каталог_*.json.gz` зафіксовані відбитками; збагачення використане тільки там, де існує опис форми кадру.', '',
        '## Відтворення', '',
        'У дереві цього коміту, з незмінними джерелами базового main; Python 3.12, установлені залежності продукту. Повтор основного виміру не ходить у мережу й пише тільки в задану теку:', '',
        '```powershell',
        'python3 -X utf8 аудит/проби/річ_запис_каталог.py --вихід /tmp/річ-повтор   # п.1–2, ~2 хв, без мережі',
        'python3 -X utf8 аудит/проби/річ_запис_блок.py                              # п.3: поля проти блоку, без мережі',
        'python3 -X utf8 аудит/проби/річ_запис_частки.py                            # п.3: частки',
        'python3 -X utf8 аудит/проби/річ_запис_звіт.py                              # звірка й цей README',
        '```', '',
        'Перша команда повторює функції продукту; очікувані числа наведено вище, gzip/JSON детерміновані. Друга звіряє збережені рядки з підсумком, унікальність ID, SHA256 усіх входів, HTML і 20 кадрів; не підміняє незалежну перевірку. Остаточний CLI повторено повністю на `main` з SHA вище (спроба 2); числа п.1–2 збіглися зі спробою 1 (651adb1b), яка вимірювала `main` 7d80dcb5.', '',
        'Мережеві кроки (стан сайтів міг змінитися, для повтору чисел не потрібні): `node аудит/проби/річ_запис_рендер.js` (DOM звичайним Chromium), `річ_запис_заміна.py` (кандидати-замінники), `річ_запис_докази.py --кадри` (кадри прикладів, спроба 1). Збережені HTML — `річ_запис_каталог_2026_10_30/html/`.', '',
        '## Межі зіставлення читачів', '',
        'У `читачі.jsonl.gz` є кожний офер, всі викликані виходи, вхід назви/категорії, опис кадру, кадр і всі розбіжні пари. `{}` у читача верхнього означає незастосовність, а не `тип=None`. Відсутній читач кадру означає, що опису кадру немає.', '',
        'Рядки нижче — адреси виконаних функцій, не статичний прилад кореня:', '',
    ]
    for імя, адреса in sorted(підсумок['функції'].items()):
        текст.append('- `' + імя + '` — `' + адреса + '`.')
    текст += ['', 'Огляд 25.10 описує попередню архітектуру: `чистка.тип_назви` вже вилучено, `тип_набору` делегує `вид_речі`, `назва_речі.іменник_речі` повертає позицію слова, а `verify._зона_слова` — зону тіла. Позиція/зона й альтернативний дозволений слот не порівнювалися з основним типом/слотом. Виклики фасадів використовують ті самі функції. Повтор жнив використовує **поля з фіда** (`категорія_магазину`, назва, URL), а не відновлює невідомий історичний вхід усіх жнив. Виходи жнив і опису кадру не є незалежними читачами готового коду.', '',
        'У 744 випадках треба відділити відсічення каналу/НЕ_ОДЯГ від класифікації; число не названо кількістю хибних слотів. Перший приклад — комплект мінісумочки із гаманцем: класифікатор дає «комплект», жіночий читач слота — None.', '',
        '## Причини кожного відсутнього типу', '', '| Причина з виконання словника | Оферів |', '|---|---:|']
    for причина, ч in sorted(підсумок['причини'].items()):
        текст.append(f'| {причина} | {ч} |')
    текст += ['', 'Доказ кожного — ID, URL, сира назва, назва суду, джерело назви, категорія, оголошений тип, точна голова після обмеження опису та результат `предмет_типу` для назви/голови/категорії. «Нема прийнятого іменника» означає результат штатного словника, а не експертне твердження, що назва не називає одяг.', '',
        '## Розклад за крамницями', '', '| Крамниця | Весь фід | Різні виходи | Без типу |', '|---|---:|---:|---:|']
    for к, ч in sorted(підсумок['крамниці'].items()):
        текст.append(f"| {к} | {ч['речей']} | {ч.get('розбіжні', 0)} | {ч.get('без_типу', 0)} |")
    текст += ['', '## Розклад за парами', '', '| Пара / поле | Різні | Спільне покриття |', '|---|---:|---:|']
    for к, ч in sorted(підсумок['пари'].items()):
        текст.append(f"| {к} | {ч} | {підсумок['покриття_пар'][к]} |")
    текст += ['', 'Розклад кожної пари за крамницею — `підсумок.json` → `пари_крамниці`; нульові пари — `покриття_пар`.', '',
        '## 20 прикладів із кадром', '', 'Кадри завантажені й оглянуті на контактному аркуші; це доказ вигляду прикладів, не перевірка власника кожного кадру.', '',
        '![20 прикладів](приклади_20.png)', '', 'Усі виходи кожного з 20 прикладів — `приклади_20.json`, оригінальні файли — `кадри/`, відбитки — `кадри.json`. На аркуші підписані слот класифікатора / слот повтору жнив; інші розбіжності див. JSON.', '',
        '## Поля з чужого блоку (п.3)', '',
        '**Вибірка: 144 сторінки, 48 крамниць по 3.** Зерно 11658: з кожної крамниці `Random(11658).sample` трьох унікальних URL (крамниці й URL відсортовані) — `вибірка.json`, 156 URL. Придатність: HTTP 200 і понад 500 знаків тексту після вилучення script/style. 26 порожніх HTTP 200 (JS-сторінки) відкрито звичайним Chromium без профілю (`річ_запис_рендер.js`): 24 стали придатні, збережено той самий URL. Для решти замінник — наступний за порядком URL тієї ж крамниці (`річ_запис_заміна.py`; архіву 5.3 і сирих жнив у цій сесії нема): miraton.ua — 2 адреси замінено (`вибірка_п3.json`, поле `замість`). Збережений HTML кожної з 144 сторінок — `html/`, зіставлення — `блоки.json`, рішення очима — `очі_п3.json`, частки — `частки.json`.', '',
        '**Крамниці без жодної придатної сторінки (не в частці):** ' + '; '.join(f"{р['крамниця']} — {р['причина'].split(';')[0]}" for р in без_сторінок) + '. Захисту не обходили; перевірено головну сторінку й до 5 наступних URL кожної такої крамниці.', '',
        '**Метод.** Поле запису (назва, опис, склад, розділ) проти сторінки: шматки поля шукаються в JSON-LD Product / мета-описі, у блоці товару (найвищий предок заголовка без колонтитулів, меню й блоків інших товарів) і поза ним. «Чужий» — текст не з блоку цього товару: мітки вкладок інтерфейсу («Характеристики Доставка і оплата Відгуки…») у полі опису, список інших товарів («Рекомендовані для поєднання…»), SEO-мета замість опису («Купити … ✓ В наявності», «за ціною … грн»), хвіст заголовка вкладки в назві («… ціни на Сукні в інтернет-магазині … a LOT», «【MustHave ❤️】ціна»), речення з опису в полі назви. Ознаки — регулярні вирази `ОЗНАКИ` у `річ_запис_блок.py`; кожну спрацьовану ознаку й кожну розбіжність перегляд очима текстових витягів збереженого HTML — не знімків (`очі_п3.json`, 19 рішень з причиною) та вибірково 14 «своїх» описів (усі — у `product-description`/вкладці опису товару).', '',
        '| Поле | Чужих | Непорожніх (знаменник) | Частка | Не на сторінці, але не чуже (мова, зміна сайту) | Порожнє в записі |', '|---|---:|---:|---:|---:|---:|']
    for поле in ['назва', 'опис', 'склад']:
        в = частки['поля'][поле]
        знам = sum(в.get(к, 0) for к in ('свій', 'чужий', 'нема'))
        текст += [f"| {поле} | {в.get('чужий', 0)} | {знам} | {100 * в.get('чужий', 0) / знам:.1f} % | {в.get('нема', 0)} | {в.get('порожнє', 0)} |"]
    текст += ['', f"Сторінок із чужим принаймні в одному полі: **{len({ч['id'] for ч in частки['чужі']})} з 144** ({100 * len({ч['id'] for ч in частки['чужі']}) / 144:.1f} %). Склад: чужого не знайдено (формат запису лише інший порядок «60% віскоза» / «віскоза 60%»). Сторінка brenda.ua/gucci-70 — не картка товару (сторінка бренду з SEO-текстом), виключена з усіх чотирьох полів.", '',
        '### За крамницями (чужих полів назва / опис з трьох сторінок)', '', '| Крамниця | назва | опис |', '|---|---:|---:|']
    for к, в in sorted(частки['за_крамницею'].items()):
        if в['назва'].get('чужий') or в['опис'].get('чужий'):
            текст.append(f"| {к} | {в['назва'].get('чужий', 0)} | {в['опис'].get('чужий', 0)} |")
    текст += ['', f"Крамниць із чужим полем: **{sum(1 for в in частки['за_крамницею'].values() if в['назва'].get('чужий') or в['опис'].get('чужий'))} з 48**. Решта 36 — чужого у вибірці нема.", '',
        '### Види чужого (за ознакою)', '', '| Поле | Вид | Сторінок |', '|---|---|---:|']
    for (поле, вид), ч in sorted(collections.Counter((ч['поле'], ч['вид']) for ч in частки['чужі']).items()):
        текст.append(f'| {поле} | {вид} | {ч} |')
    текст += ['', 'Повний перелік (id, поле, вид, URL) — `частки.json` → `чужі`.', '',
        '### Розділ', '', 'Розділ записів береться з таксономії крамниці, а не з блоку сторінки, тому «чужий блок» тут не встановлюється; міряється збіг з крихтами сторінки. ' + ', '.join(f'{к}: {в}' for к, в in sorted(частки['поля']['розділ'].items())) + '. «Інший блок» — розділ записано, слово є на сторінці лише поза крихтами (меню); «нема» — теги колекцій («Sale», «new»), склеєні через кому, або внутрішні групи («низ», «shoes»), яких на сторінці нема.', '',
        '### Межі', '', '- Вибірка 144 сторінок — не частка каталогу: чужі шматки знайдено за ознаками тексту; чужий текст без ознаки (наприклад, опис сусіднього товару без маркерів) цим вимірюванням не ловиться: частка чужих — нижня межа.',
        '- Сторінки зняті 30.10.2026; запис каталогу міг бути складений раніше (ціна у SEO-мета відрізняється від поточної); «нема на сторінці» не доводить чужості.',
        '- Блок товару знайдено машиною, чужість ознак перевірено очима по HTML; 3 сторінки без `h1` і JSON-LD — блок не визначено, поле перевірено лише за ознаками й пошуком по сторінці.', '',
        '## ДО → ПІСЛЯ та межі', '',
        'ДО: суцільних чисел у паспорті не було. ПІСЛЯ: п.1 — 2 972 з 30 375 оферів з різними виходами слота (744 серед входів готового запису); п.2 — 1 231 без типу з причиною кожного; п.3 — вибірка 144 сторінки / 48 крамниць: чужих назв 10 (7,0 %), чужих описів 17 (14,5 %), складу 0. Продукт, каталог, прилади кореня та храповик не змінені.', '']
    (тека / 'README.md').write_text('\n'.join(текст), encoding='utf-8')
    print(f"Звірено: {len(речі)} оферів, {len(без_типу)} без типу, 20 кадрів, {len(п3)} сторінок п.3.")


if __name__ == '__main__':
    main()
